"""Six-slide, self-contained local demo from actual QA captures and released values."""
import base64,json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
qa=root/'docs/qa/cinema/product-final-visual'
def uri(path,mime='image/png'):return 'data:'+mime+';base64,'+base64.b64encode(path.read_bytes()).decode()
def img(name,cls=''):return '<img class="'+cls+'" src="'+uri(qa/name)+'" alt="Actual RIMWAKE screenshot">'
slides=[]
def slide(title,body):
 n=len(slides)+1;slides.append(f'<section class="slide"><header>RIMWAKE / LUNAR LANDING SITE NAVIGATOR</header><h1>{title}</h1>{body}<footer><span>Independent educational project / science provisional</span><span>{n:02} / 06</span></footer></section>')
r=json.loads((root/'public/data/release.json').read_text());times=sorted({row['timestamp_utc'] for row in r['refined_samples']});values=[next(row['elevation_deg'] for row in r['refined_samples'] if row['site_id']=='im1' and row['body_id']==10 and row['timestamp_utc']==times[i]) for i in [3,4]]
def signed(x):return ('&minus;' if x<0 else '+')+f'{abs(x):.3f}'+'&deg;'
slide('WHERE YOU STAND.', '<div class="hero">'+img('experience-1440.png')+'</div><p class="caption">One world. Two lunar perspectives. A source-backed scientific experience.</p>')
slide('ONE MOON. TWO PLACES.', '<div class="columns"><div><h2>One moment can produce<br>different local skies.</h2><p>Compare the Sun and Earth at two approximate published southern landing coordinates.</p><p>A / Odysseus<br>80.13 S / 1.44 E</p><p>B / Athena<br>84.7906 S / 29.1957 E</p><p class="note">Hypothetical reference-ellipsoid observers. The map provides geographic context; it does not calculate terrain obstruction.</p></div>'+img('details/map-390.png','portrait')+'</div>')
slide('ONE CLOCK. TWO LOCAL SKIES.', '<div class="wide">'+img('explorer-1440.png')+'</div><p class="caption">14 November 2026, 00:00 UTC. Sun below the plane at A, above at B. Earth has the opposite classification. One shared source release.</p>')
slide('TEN MINUTES. A THRESHOLD.', '<div class="crossing"><div><h2>Follow a real<br>sampled crossing.</h2><p>16 November 2026<br>03:30 to 03:40 UTC</p><p class="angles">'+signed(values[0])+'<br>'+signed(values[1])+'</p><p class="note">Sun-centre elevation at A. A sign change brackets a threshold; the exact crossing instant remains unresolved. Selected example, not a typical-condition claim.</p></div>'+img('details/discovery-before-390.png','portrait')+img('details/discovery-after-390.png','portrait')+'</div>')
slide('FOLLOW THE EVIDENCE.', '<div class="columns"><div><h2>The source.<br>The sample.<br>The limit.</h2><p>NASA NSSDCA coordinates.<br>JPL Horizons angular positions.<br>Archived requests, hashes and raw responses.</p><p class="note">3,364 hourly readings and 28 refined readings. No position interpolation. Independent ephemeris validation and exact frame reconciliation remain open.</p></div>'+img('details/evidence-390.png','portrait')+'</div>')
slide('MAKE LUNAR GEOMETRY UNDERSTANDABLE.', '<div class="value"><div><h2>LOCATE.</h2><p>Find the observers and understand the geometric question.</p></div><div><h2>COMPARE.</h2><p>Move one clock, follow transitions, or find a matching sampled run.</p></div><div><h2>VERIFY.</h2><p>Reopen the exact observation, inspect its source and export a summary.</p></div></div><p>For educators, the public and technically curious explorers.</p><p class="note">Terrain, finite discs, eclipses, power and RF performance are excluded. NASA does not endorse this project. NASA Goddard/LRO imagery and JPL/NSSDCA data are credited in the application. Human owner direction; Codex assisted code, processing, tests and text. No generated imagery or audio.</p>')
font=uri(root/'node_modules/@fontsource/barlow-condensed/files/barlow-condensed-latin-600-normal.woff2','font/woff2');body=uri(root/'node_modules/@fontsource/ibm-plex-sans/files/ibm-plex-sans-latin-400-normal.woff2','font/woff2')
css='@font-face{font-family:Display;src:url(FONT)}@font-face{font-family:Body;src:url(BODY)}*{box-sizing:border-box}body{margin:0;background:#080d13;color:#eef0ea;font-family:Body,Arial}.slide{width:1280px;height:720px;padding:32px 48px 45px;position:relative;break-after:page;overflow:hidden}header{font-size:12px;letter-spacing:.12em;color:#b5c1d0}h1{font:600 58px/.95 Display;margin:20px 0 24px;letter-spacing:-.015em}h2{font:600 42px/1.05 Display;margin:0 0 22px}p{font-size:22px;line-height:1.55;margin:0 0 20px;color:#c6d0da}.hero{height:475px;overflow:hidden}.hero img{width:100%;height:100%;object-fit:cover;object-position:center 45%}.caption{font-size:17px;line-height:1.4;margin-top:16px}.columns{display:grid;grid-template-columns:1fr 450px;gap:55px;height:490px}.portrait{max-width:100%;height:485px;object-fit:contain;justify-self:center}.note{font-size:16px;line-height:1.6;color:#aebdcd}.wide{height:480px}.wide img{width:100%;height:100%;object-fit:contain}.crossing{display:grid;grid-template-columns:1fr 250px 250px;gap:30px;height:490px}.angles{color:#efb86f;font:600 52px/1.12 Display;margin:22px 0}.value{display:grid;grid-template-columns:repeat(3,1fr);gap:40px;margin:65px 0 50px}.value>div{border-top:1px solid #617386;padding-top:25px}.value p{font-size:23px}footer{position:absolute;bottom:18px;left:48px;right:48px;display:flex;justify-content:space-between;font-size:11px;color:#a7b5c6}@page{size:1280px 720px;margin:0}@media screen{.slide{margin:0 auto 20px;box-shadow:0 0 0 1px #3d4d5d}}'.replace('FONT',font).replace('BODY',body)
(root/'docs/demo-slides.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><title>RIMWAKE local demonstration</title><style>'+css+'</style>'+''.join(slides)+'</html>',encoding='utf-8')
gallery=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>RIMWAKE before and after</title><style>body{background:#090d13;color:#edf0ea;font:16px/1.7 Arial;padding:30px 4vw}.pair{display:grid;grid-template-columns:1fr 1fr;gap:24px}img{width:100%}a{color:inherit}section{margin:40px 0;border-top:1px solid #657484}p{color:#b8c5d3}@media(max-width:700px){.pair{grid-template-columns:1fr}}</style><h1>RIMWAKE / Before and after.</h1><p>Actual browser captures. Before: Meridian Cut, v6 QA round 2. After: current local production build. The scientific release is unchanged.</p>']
for title,before,after in [('The opening','discover','experience'),('The scientific interaction','explore','explorer')]:gallery.append(f'<section><h2>{title}</h2><div class="pair"><div><p>Before / Meridian Cut</p><img src="qa/v6/round-2/{before}-1440.png" alt="Previous interface"></div><div><p>After / Current production preview</p><img src="qa/cinema/product-final-visual/{after}-1440.png" alt="Current interface"></div></div></section>')
gallery.append('<p><a href="PRODUCT_TRANSFORMATION.md">Feature matrix and remaining gates</a> / <a href="demo-slides.pdf">Six-slide demonstration</a></p></html>');(root/'docs/before-after.html').write_text(''.join(gallery),encoding='utf-8')
print('Created six self-contained slides and the before/after gallery from actual captures.')
